S[1786] = function ($sc, $this) {
  var $tgt = $this, $base = $this;
  var $u = { sc: $sc, tgt: $tgt, base: $this, this: $this };
  var t1, t2, t3, t4, t5, t6, t7, t8;
  var $s = [];
  var $b = 0;
  for (;;) switch ($b) {
  case 0:
    t1 = $.eq($.gm($.get($sc, "_root"), "midfight"), false);
    $s.push(t1);
    if (!t1) { $b = 2; continue; }
    $b = 1; continue;
  case 1:
    t2 = $s.pop();
    t3 = $.eq($.gm($.gm($.get($sc, "_root"), "playermove"), $.gm($.get($sc, "_root"), "turnnum")), "enemy1");
    $s.push(t3);
    $b = 2; continue;
  case 2:
    t4 = $s.pop();
    if (!$.bool(t4)) { $b = 10; continue; }
    $b = 3; continue;
  case 3:
    if (!$.bool($.lt(0, $.gm($.get($sc, "_root"), "enemy1life")))) { $b = 8; continue; }
    $b = 4; continue;
  case 4:
    if (!$.bool($.lt(0, $.gm($.get($sc, "_root"), "hero2life")))) { $b = 6; continue; }
    $b = 5; continue;
  case 5:
    t5 = $.random(2);
    $.set($sc, "randtarg", (t5 + 1));
    $.sm($.get($sc, "_root"), "enemytarget", $.add("hero", $.get($sc, "randtarg")));
    $b = 7; continue;
  case 6:
    $.sm($.get($sc, "_root"), "enemytarget", "hero1");
    $b = 7; continue;
  case 7:
    t6 = $.get($sc, "attacks");
    t7 = $.random($.get($sc, "numofmoves"));
    t8 = $.callMethod($.get($sc, "_root"), "Fight", [$.gm(t6, t7)]);
    if ($base.removed) return;
    $.sm($.get($sc, "_root"), "midfight", true);
    $b = 8; continue;
  case 8:
    $.sm($.get($sc, "_root"), "turnnum", ($.n($.gm($.get($sc, "_root"), "turnnum")) + 1));
    if (!$.eq($.gm($.get($sc, "_root"), "turnnum"), 4)) { $b = 10; continue; }
    $b = 9; continue;
  case 9:
    $.sm($.get($sc, "_root"), "turnnum", 0);
    $b = 10; continue;
  default: return;
  }
};
